// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 ts1, uint256 ts2, address actor) public {
        // wide admissible domain: any two strictly increasing timestamps, any actor
        ts1 = bound(ts1, 1, type(uint256).max / 4);
        ts2 = bound(ts2, 1, type(uint256).max / 4);
        vm.assume(ts2 > ts1);
        vm.assume(actor != address(0) && actor != address(c));

        // first successful call at ts1
        vm.warp(ts1);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok1,) = address(c).call{value: 10 ether}("");

        // second successful call at ts2 (admissible since ts2 > ts1)
        vm.warp(ts2);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok2,) = address(c).call{value: 10 ether}("");

        // single general rule: whenever both calls succeed, pastBlockTime must
        // have been advanced to the latest call's timestamp ts2
        assertTrue(ok1 && ok2 && c.pastBlockTime() == ts2);
    }
}
